/**
 * REGISTRE_RGPD.json is generated by scripts/gdpr-suite.mjs. Contract: the committed file is exactly what the generator produces, every duration in it comes from
 * the code (RETENTION in cron/gdpr-purge, RETENTION_POLICY_REGISTRY in privacy.js), and it makes no unsupported claim (DPO, signed DPA, Zero-Knowledge, Gemini as recipient).
 * Reference: LEGAL_FR/06_REGISTRE_TRAITEMENTS.md §3.
 */
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { RETENTION } from '../../api/_handlers/cron/gdpr-purge.js';
import { RETENTION_POLICY_REGISTRY } from '../../api/_services/privacy.js';
import { buildRegistre, generateRegistreContent, readCodeSources, REGISTRE_DATE_REVISION, CONTACT_PROTECTION_DONNEES } from '../../scripts/gdpr-suite.mjs';

const ROOT = path.resolve(__dirname, '../..');
const fileText = fs.readFileSync(path.join(ROOT, 'REGISTRE_RGPD.json'), 'utf-8');
const registre = JSON.parse(fileText);
const conservations = registre.traitements.flatMap((t) => t.conservation.map((c) => ({ id: t.id, ...c })));

describe('REGISTRE_RGPD.json — generated, consistent with the code', () => {
  it('equals what scripts/gdpr-suite.mjs generates (regenerate with `node scripts/gdpr-suite.mjs`)', () => {
    expect(fileText).toBe(generateRegistreContent(ROOT));
  });

  it('static parsing of the sources matches the runtime constants', () => {
    const { retention, registry } = readCodeSources(ROOT);
    expect(retention).toEqual(RETENTION);
    for (const [key, r] of Object.entries(RETENTION_POLICY_REGISTRY)) {
      expect(registry[key], key).toEqual({ durationDays: r.durationDays, action: r.action, implementedBy: r.implementedBy ?? null });
    }
  });

  it('every RETENTION-sourced duration equals the purge constant', () => {
    const fromCron = conservations.filter((c) => c.source?.startsWith('RETENTION.'));
    expect(fromCron.length).toBeGreaterThan(0);
    for (const c of fromCron) {
      const key = c.source.slice('RETENTION.'.length);
      expect(c.duree_jours, `${c.id} ${c.source}`).toBe(RETENTION[key]);
      expect(c.description).toContain(String(RETENTION[key]));
    }
    // every purge constant is used at least once
    const used = new Set(fromCron.map((c) => c.source.slice('RETENTION.'.length)));
    for (const key of Object.keys(RETENTION)) expect(used.has(key), key).toBe(true);
    expect(conservations.find((c) => c.source === 'RETENTION.CONVERSATION_LOG_DAYS' && c.id === 'T08').duree_jours).toBe(90);
  });

  it('every registry-sourced duration equals RETENTION_POLICY_REGISTRY, and unimplemented rules say "non appliqué"', () => {
    const fromRegistry = conservations.filter((c) => c.source?.startsWith('RETENTION_POLICY_REGISTRY.'));
    expect(fromRegistry.length).toBeGreaterThan(0);
    for (const c of fromRegistry) {
      const r = RETENTION_POLICY_REGISTRY[c.source.slice('RETENTION_POLICY_REGISTRY.'.length)];
      expect(c.duree_jours, c.source).toBe(r.durationDays);
      expect(c.statut, c.source).toBe(r.implementedBy === null ? 'non appliqué' : 'appliqué');
    }
    const inactive = fromRegistry.find((c) => c.source === 'RETENTION_POLICY_REGISTRY.INACTIVE_ACCOUNT');
    expect(RETENTION_POLICY_REGISTRY.INACTIVE_ACCOUNT.implementedBy).toBeNull();
    expect(inactive.statut).toBe('non appliqué');
    expect(inactive.description).toMatch(/^non appliqué/);
    const shared = conservations.filter((c) => c.source_registre === 'RETENTION_POLICY_REGISTRY.SHARED_DIAGNOSTIC');
    expect(shared.length).toBeGreaterThan(0);
    for (const c of shared) expect(c.duree_jours_registre).toBe(RETENTION_POLICY_REGISTRY.SHARED_DIAGNOSTIC.durationDays);
  });

  it('makes no unsupported claim', () => {
    expect(fileText).not.toMatch(/zero[- ]?knowledge/i);
    expect(fileText).not.toMatch(/"dpa":\s*"Oui"/i);
    expect(fileText).not.toMatch(/dpo@/i);
    expect(fileText).not.toMatch(/bcrypt/i);
    expect(fileText).not.toMatch(/"dpo_contact"/);
    expect(registre.dpo).toBeNull();
    expect(registre.contact_protection_donnees).toBe(CONTACT_PROTECTION_DONNEES);
    expect(registre.organisme.statut).toBe('IN_FORMATION');
    for (const s of registre.sous_traitants) expect(s.dpa, s.nom).toBe('inconnu / non signé');
  });

  it('Gemini is blocked, not a recipient; the assistant uses local Ollama', () => {
    expect(registre.sous_traitants.some((s) => /gemini/i.test(s.nom))).toBe(false);
    const gemini = registre.services_non_destinataires.find((s) => /gemini/i.test(s.nom));
    expect(gemini.statut).toBe('bloqué');
    for (const t of registre.traitements) for (const d of t.destinataires) expect(d).not.toMatch(/gemini/i);
    const assistant = registre.traitements.find((t) => t.id === 'T08');
    expect(assistant.modele_ia).toMatch(/Ollama/);
  });

  it('Vercel: fra1 (EU) region, US contracting entity, unverified transfer mechanism', () => {
    const vercel = registre.sous_traitants.find((s) => s.nom === 'Vercel');
    expect(vercel.localisation).toMatch(/fra1/);
    expect(vercel.entite_contractante).toMatch(/USA/);
    expect(vercel.mecanisme_transfert).toBe('NON VÉRIFIÉ');
  });

  it('diagnostic, OpenFisca and erasure are described as implemented', () => {
    const diag = registre.traitements.find((t) => t.id === 'T02');
    expect(diag.lieux_traitement.join(' ')).toMatch(/non stockées par \/api\/diagnostic/);
    expect(diag.lieux_traitement.join(' ')).toMatch(/SharedDiagnostic\.situation/);
    expect(diag.services_refuses.join(' ')).toMatch(/OpenFisca.*refusé en production/);
    expect(registre.droits_exercables.join(' ')).toMatch(/revue humaine/);
    expect(registre.droits_exercables.join(' ')).toMatch(/\/api\/auth\/export-data/);
    expect(registre.droits_exercables.join(' ')).not.toMatch(/gdpr-suite/);
  });

  it('date_mise_a_jour is the fixed revision date, not the run date', () => {
    expect(registre.date_mise_a_jour).toBe('2026-10-25');   // launch-readiness campaign: encryption of the shared answers and of the appointment messages
    expect(REGISTRE_DATE_REVISION).toBe('2026-10-25');
    const built = buildRegistre(readCodeSources(ROOT));
    expect(built.date_mise_a_jour).toBe(REGISTRE_DATE_REVISION);
  });

  it('the script no longer contains the clear-text export sub-command', () => {
    const script = fs.readFileSync(path.join(ROOT, 'scripts/gdpr-suite.mjs'), 'utf-8');
    expect(script).not.toMatch(/exports['"`]\)/);
    expect(script).not.toMatch(/new Date\(\)/);
    expect(script).not.toMatch(/src\/db\/index/);
  });
});
